{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.rolling_30_days_dashboard AS WITH capsule_launch AS ( SELECT CAPSULE, LAUNCH_DATE FROM VALUES (\'Street FC\', \'2026-06-23\'::DATE), (\'Street FC Plus\', \'2026-06-23\'::DATE), (\'botanical THEME\', \'2026-07-11\'::DATE), (\'Embroided Shirts\', \'2026-07-16\'::DATE), (\'GOLF POLO THEME\', \'2026-07-27\'::DATE), (\'PHOTO PRINT\', \'2026-08-06\'::DATE), (\'Try Less Denim\', \'2026-08-14\'::DATE), (\'Festive - 1\', NULL), (\'Printed Shirts\', \'2026-09-04\'::DATE), (\'Luxe\', \'2026-09-18\'::DATE), (\'Technical\', \'2026-09-24\'::DATE), (\'Noir\', \'2026-10-09\'::DATE), (\'Puffer\', \'2026-10-16\'::DATE), (\'BISMIL2.0\', \'2026-10-23\'::DATE), (\'FLANNEL\', \'2026-10-30\'::DATE), (\'SWEATERS\', \'2026-11-06\'::DATE) AS t(CAPSULE, LAUNCH_DATE) ), sku_mapping AS ( SELECT DISTINCT UPPER(TRIM(SKU)) AS SKU, TRIM(COLLECTION) AS CAPSULE FROM snitch_db.maplemonk.collection_sku_mapped_sheet1 WHERE SKU IS NOT NULL AND COLLECTION IS NOT NULL ), flannel_skus AS ( SELECT DISTINCT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP FROM VALUES (\'4MSS4904-01\'), (\'4MSS4480-01\'), (\'4MSS4903-01\'), (\'4MSS4905-01\'), (\'4MSS4676-01\'), (\'4MSS4554-01\'), (\'4MSS4523-01\'), (\'4MSS4555-01\'), (\'4MSS4526-01\'), (\'4MSS3536-02\'), (\'4MSS4484-02\'), (\'4MSS4905-02\'), (\'4MSS4906-02\'), (\'4MSS4555-02\'), (\'4MOS1052-01\'), (\'4MOS1050-01\'), (\'4MOS1042-01\'), (\'4MSS4472-02\'), (\'4MSS3631-02\') AS t(SKU_GROUP) ), sku_mapping_final AS ( SELECT sm.SKU, sm.CAPSULE FROM sku_mapping sm WHERE NOT EXISTS ( SELECT 1 FROM flannel_skus f WHERE f.SKU_GROUP = sm.SKU ) UNION ALL SELECT f.SKU_GROUP AS SKU, \'FLANNEL\' AS CAPSULE FROM flannel_skus f ), flannel_current_inventory AS ( SELECT UPPER(TRIM(c.SKU_GROUP)) AS SKU_GROUP, SUM(c.INV_CURRENT) AS CURRENT_INVENTORY FROM snitch_db.maplemonk.category_overall_data c INNER JOIN flannel_skus f ON UPPER(TRIM(c.SKU_GROUP)) = f.SKU_GROUP GROUP BY UPPER(TRIM(c.SKU_GROUP)) ), last_30_days AS ( SELECT UPPER(TRIM(h.SKU_GROUP)) AS SKU_GROUP, sm.CAPSULE, cl.LAUNCH_DATE, SUM( CASE WHEN LOWER(TRIM(sm.CAPSULE)) IN (\'technical\', \'flannel\') AND cl.LAUNCH_DATE IS NOT NULL AND DATEDIFF(DAY, cl.LAUNCH_DATE, CURRENT_DATE()) < 30 THEN CASE WHEN TO_DATE(h.DATE) >= cl.LAUNCH_DATE THEN h.GROSS_QUANTITY ELSE 0 END ELSE CASE WHEN TO_DATE(h.DATE) >= CURRENT_DATE() - 30 THEN h.GROSS_QUANTITY ELSE 0 END END ) AS LAST_30_QTY, SUM( CASE WHEN LOWER(TRIM(sm.CAPSULE)) IN (\'technical\', \'flannel\') AND cl.LAUNCH_DATE IS NOT NULL AND DATEDIFF(DAY, cl.LAUNCH_DATE, CURRENT_DATE()) < 30 THEN CASE WHEN TO_DATE(h.DATE) >= cl.LAUNCH_DATE THEN h.GROSS_SALES ELSE 0 END ELSE CASE WHEN TO_DATE(h.DATE) >= CURRENT_DATE() - 30 THEN h.GROSS_SALES ELSE 0 END END ) AS LAST_30_GROSS_SALES, SUM( CASE WHEN LOWER(TRIM(sm.CAPSULE)) IN (\'technical\', \'flannel\') AND cl.LAUNCH_DATE IS NOT NULL AND DATEDIFF(DAY, cl.LAUNCH_DATE, CURRENT_DATE()) < 30 THEN CASE WHEN TO_DATE(h.DATE) >= cl.LAUNCH_DATE THEN h.DISCOUNT_AMOUNT ELSE 0 END ELSE CASE WHEN TO_DATE(h.DATE) >= CURRENT_DATE() - 30 THEN h.DISCOUNT_AMOUNT ELSE 0 END END ) AS LAST_30_DISCOUNT, ROUND( SUM( CASE WHEN LOWER(TRIM(sm.CAPSULE)) IN (\'technical\', \'flannel\') AND cl.LAUNCH_DATE IS NOT NULL AND DATEDIFF(DAY, cl.LAUNCH_DATE, CURRENT_DATE()) < 30 THEN CASE WHEN TO_DATE(h.DATE) >= cl.LAUNCH_DATE THEN h.GROSS_SALES ELSE 0 END ELSE CASE WHEN TO_DATE(h.DATE) >= CURRENT_DATE() - 30 THEN h.GROSS_SALES ELSE 0 END END ) / NULLIF( SUM( CASE WHEN LOWER(TRIM(sm.CAPSULE)) IN (\'technical\', \'flannel\') AND cl.LAUNCH_DATE IS NOT NULL AND DATEDIFF(DAY, cl.LAUNCH_DATE, CURRENT_DATE()) < 30 THEN CASE WHEN TO_DATE(h.DATE) >= cl.LAUNCH_DATE THEN h.GROSS_QUANTITY ELSE 0 END ELSE CASE WHEN TO_DATE(h.DATE) >= CURRENT_DATE() - 30 THEN h.GROSS_QUANTITY ELSE 0 END END ), 0 ), 2 ) AS LAST_30_ASP FROM snitch_db.maplemonk.horizontal_sales_categories h INNER JOIN sku_mapping_final sm ON UPPER(TRIM(h.SKU_GROUP)) = sm.SKU LEFT JOIN capsule_launch cl ON LOWER(TRIM(sm.CAPSULE)) = LOWER(TRIM(cl.CAPSULE)) GROUP BY UPPER(TRIM(h.SKU_GROUP)), sm.CAPSULE, cl.LAUNCH_DATE ), first_sales AS ( SELECT UPPER(TRIM(SKU_GROUP)) AS SKU_GROUP, MIN(DATE) AS FIRST_SALE_DATE FROM snitch_db.maplemonk.horizontal_sales_categories WHERE GROSS_QUANTITY > 0 GROUP BY 1 ), sales_periods AS ( SELECT UPPER(TRIM(h.SKU_GROUP)) AS SKU_GROUP, sm.CAPSULE, cl.LAUNCH_DATE, SUM( CASE WHEN LOWER(TRIM(sm.CAPSULE)) = \'flannel\' AND cl.LAUNCH_DATE IS NOT NULL THEN CASE WHEN DATEDIFF(DAY, cl.LAUNCH_DATE, CURRENT_DATE()) < 30 AND TO_DATE(h.DATE) >= cl.LAUNCH_DATE THEN h.GROSS_QUANTITY WHEN DATEDIFF(DAY, cl.LAUNCH_DATE, CURRENT_DATE()) >= 30 AND TO_DATE(h.DATE) >= CURRENT_DATE() - 30 THEN h.GROSS_QUANTITY ELSE 0 END WHEN LOWER(TRIM(sm.CAPSULE)) = \'technical\' AND cl.LAUNCH_DATE IS NOT NULL AND DATEDIFF(DAY, cl.LAUNCH_DATE, CURRENT_DATE()) < 30 THEN CASE WHEN TO_DATE(h.DATE) >= cl.LAUNCH_DATE THEN h.GROSS_QUANTITY ELSE 0 END WHEN LOWER(TRIM(sm.CAPSULE)) = \'technical\' THEN CASE WHEN TO_DATE(h.DATE) >= CURRENT_DATE() - 30 THEN h.GROSS_QUANTITY ELSE 0 END ELSE CASE WHEN TO_DATE(h.DATE) >= fs.FIRST_SALE_DATE THEN h.GROSS_QUANTITY ELSE 0 END END ) AS CUMULATIVE_SALES_QTY, SUM( CASE WHEN cl.LAUNCH_DATE IS NOT NULL AND TO_DATE(h.DATE) >= cl.LAUNCH_DATE THEN h.GROSS_QUANTITY ELSE 0 END ) AS LAUNCH_TO_DATE_SALES_QTY FROM snitch_db.maplemonk.horizontal_sales_categories h INNER JOIN sku_mapping_final sm ON UPPER(TRIM(h.SKU_GROUP)) = sm.SKU LEFT JOIN capsule_launch cl ON LOWER(TRIM(sm.CAPSULE)) = LOWER(TRIM(cl.CAPSULE)) INNER JOIN first_sales fs ON UPPER(TRIM(h.SKU_GROUP)) = UPPER(TRIM(fs.SKU_GROUP)) GROUP BY UPPER(TRIM(h.SKU_GROUP)), sm.CAPSULE, cl.LAUNCH_DATE ), inwards AS ( SELECT UPPER(TRIM(SKUGROUP)) AS SKU_GROUP, SUM(PUTAWAY_COMPLETED_QUANTITY) AS TOTAL_INWARD_QTY, SUM( CASE WHEN PUTAWAY_COMPLETED_DATE::DATE >= CURRENT_DATE() - 30 THEN PUTAWAY_COMPLETED_QUANTITY ELSE 0 END ) AS LAST_30_INWARD_QTY FROM snitch_db.maplemonk.putaway_tracking WHERE LOWER(FINAL_TYPE) LIKE \'new%\' GROUP BY UPPER(TRIM(SKUGROUP)) ), rolling_30_metrics AS ( SELECT l.SKU_GROUP, l.CAPSULE, l.LAUNCH_DATE, l.LAST_30_QTY, l.LAST_30_GROSS_SALES, l.LAST_30_DISCOUNT, l.LAST_30_ASP, i.TOTAL_INWARD_QTY AS TOTAL_INWARD_QTY, fci.CURRENT_INVENTORY AS CURRENT_INVENTORY, fs.FIRST_SALE_DATE, sp.CUMULATIVE_SALES_QTY, sp.LAUNCH_TO_DATE_SALES_QTY, CASE WHEN LOWER(TRIM(l.CAPSULE)) IN (\'technical\', \'flannel\') THEN LEAST( DATEDIFF(DAY, l.LAUNCH_DATE, CURRENT_DATE()), 30 ) ELSE DATEDIFF(DAY, fs.FIRST_SALE_DATE, CURRENT_DATE()) END AS DAYS_ACTIVE, DATEDIFF( DAY, l.LAUNCH_DATE, CURRENT_DATE() ) AS DAYS_SINCE_LAUNCH, ROUND( CASE WHEN LOWER(TRIM(l.CAPSULE)) = \'flannel\' THEN l.LAST_30_QTY / NULLIF( l.LAST_30_QTY + fci.CURRENT_INVENTORY, 0 ) * 100 ELSE sp.CUMULATIVE_SALES_QTY / NULLIF( CASE WHEN LOWER(TRIM(l.CAPSULE)) = \'technical\' AND l.LAUNCH_DATE IS NOT NULL AND DATEDIFF(DAY, l.LAUNCH_DATE, CURRENT_DATE()) < 30 THEN i.LAST_30_INWARD_QTY ELSE i.TOTAL_INWARD_QTY END, 0 ) * 100 END, 2 ) AS STR_PERCENT_SOLD, ROUND( CASE WHEN LOWER(TRIM(l.CAPSULE)) = \'flannel\' THEN l.LAST_30_QTY / NULLIF( l.LAST_30_QTY + fci.CURRENT_INVENTORY, 0 ) * 100 ELSE l.LAST_30_QTY / NULLIF( CASE WHEN LOWER(TRIM(l.CAPSULE)) = \'technical\' AND l.LAUNCH_DATE IS NOT NULL AND DATEDIFF(DAY, l.LAUNCH_DATE, CURRENT_DATE()) < 30 THEN i.LAST_30_INWARD_QTY ELSE i.TOTAL_INWARD_QTY END, 0 ) * 100 END, 2 ) AS LAST_30_STR, CASE WHEN l.LAUNCH_DATE IS NULL THEN NULL WHEN LOWER(TRIM(l.CAPSULE)) = \'flannel\' THEN CASE WHEN DATEDIFF(DAY, l.LAUNCH_DATE, CURRENT_DATE()) = 0 THEN NULL ELSE LEAST( ROUND( ( l.LAST_30_QTY / NULLIF( l.LAST_30_QTY + fci.CURRENT_INVENTORY, 0 ) * 100 ) * 30.0 / DATEDIFF(DAY, l.LAUNCH_DATE, CURRENT_DATE()), 2 ), 100 ) END WHEN DATEDIFF(DAY, l.LAUNCH_DATE, CURRENT_DATE()) = 0 THEN NULL WHEN DATEDIFF(DAY, l.LAUNCH_DATE, CURRENT_DATE()) < 30 THEN LEAST( ROUND( ( l.LAST_30_QTY / NULLIF( CASE WHEN LOWER(TRIM(l.CAPSULE)) = \'technical\' THEN i.LAST_30_INWARD_QTY ELSE i.TOTAL_INWARD_QTY END, 0 ) ) * ( 30.0 / DATEDIFF(DAY, l.LAUNCH_DATE, CURRENT_DATE()) ) * 100, 2 ), 100 ) ELSE ROUND( l.LAST_30_QTY / NULLIF( CASE WHEN LOWER(TRIM(l.CAPSULE)) = \'technical\' THEN i.LAST_30_INWARD_QTY ELSE i.TOTAL_INWARD_QTY END, 0 ) * 100, 2 ) END AS NORMALIZED_30_STR FROM last_30_days l LEFT JOIN inwards i ON UPPER(TRIM(l.SKU_GROUP)) = UPPER(TRIM(i.SKU_GROUP)) LEFT JOIN first_sales fs ON UPPER(TRIM(l.SKU_GROUP)) = UPPER(TRIM(fs.SKU_GROUP)) LEFT JOIN sales_periods sp ON UPPER(TRIM(l.SKU_GROUP)) = UPPER(TRIM(sp.SKU_GROUP)) AND LOWER(TRIM(l.CAPSULE)) = LOWER(TRIM(sp.CAPSULE)) LEFT JOIN flannel_current_inventory fci ON UPPER(TRIM(l.SKU_GROUP)) = fci.SKU_GROUP ) SELECT r30.*, r30.LAST_30_STR AS STR, CASE WHEN LOWER(TRIM(r30.CAPSULE)) IN ( \'embroided shirts\', \'botanical theme\', \'street fc\', \'street fc plus\', \'golf polo theme\', \'photo print\', \'try less denim\', \'printed shirts\', \'luxe\', \'technical\', \'noir\', \'puffer\', \'bismil2.0\', \'flannel\', \'sweaters\' ) THEN \'YES\' ELSE \'NO\' END AS FOCUS_CAPSULE FROM rolling_30_metrics r30 ORDER BY LAST_30_GROSS_SALES DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            